logic:
if (element.querySelector('#contact-support-btn-injected')) return;

const contactUrl = '/hc/en-us/requests/new?ticket_form_id=360000931354&tf_360017817454=i_want_a_feature_or_extension_turned_on';

const wrapper = document.createElement('div');
wrapper.id = 'contact-support-btn-injected';
wrapper.style.cssText = `
  margin-top: 18px;
  padding: 14px 18px;
  background: #f0f6ff;
  border: 1.5px solid #3b6fd4;
  border-radius: 8px;
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
`;

const label = document.createElement('span');
label.textContent = '🔧 Need a feature or extension enabled on your wiki?';
label.style.cssText = `
  font-size: 14px;
  color: #333;
  flex: 1;
  min-width: 200px;
`;

const btn = document.createElement('a');
btn.href = contactUrl;
btn.textContent = 'Contact Support to Turn On a Feature';
btn.style.cssText = `
  display: inline-block;
  background: #3b6fd4;
  color: #fff !important;
  font-weight: bold;
  font-size: 14px;
  padding: 10px 20px;
  border-radius: 6px;
  text-decoration: none;
  white-space: nowrap;
  box-shadow: 0 2px 6px rgba(59,111,212,0.35);
  transition: background 0.2s;
`;
btn.onmouseenter = () => { btn.style.background = '#2a55b0'; };
btn.onmouseleave = () => { btn.style.background = '#3b6fd4'; };

wrapper.appendChild(label);
wrapper.appendChild(btn);
element.appendChild(wrapper);
